  function augmentReports(legacy){const last=read(KEY.weekly,{reply:'',at:null});return legacy+`<div class="card v86-card" style="margin-top:14px"><div class="split"><div><div class="eyebrow">AI / WEEKLY REPORT</div><h3 class="section-title">Complete AI-driven portal report</h3></div><span class="v86-pill">PERSISTENT</span></div><div class="actions"><button class="btn primary" data-v86-action="ai-weekly">Generate report</button><button class="btn" data-v86-action="ai-export-weekly">Export last report</button></div>${last.reply?`<pre class="ai-stream" style="margin-top:12px">${esc8(last.reply.slice(0,12000))}</pre>`:'<div class="empty" style="margin-top:12px">Generate the first weekly report to create a saved report artifact.</div>'}</div>`}

  function syncScheduleToEngine(){try{const e=engineState(),ov=scheduleOverrides();(v86.schedule?.papers||[]).slice(0,46).forEach((p,i)=>{const t=e.tests[i];if(!t)return;const x={...p,...(ov[p['Test ID']]||{})};t.scheduleId=x['Test ID'];t.testId=x['Test ID'];t.paperCode=x['Paper Code'];t.unlockDate=x.Date;const tm=String(x.Timing||'09:30–11:30 IST').replace(/[–—]/g,'-').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);t.accessStart=tm?String(tm[1]).padStart(2,'0')+':'+tm[2]:'09:30';t.accessEnd=tm?String(tm[3]).padStart(2,'0')+':'+tm[4]:'11:30';t.scheduleLabel=`${x['Test ID']} • ${x.Type} • ${x['Core Subject']}`;t.level=x.Level;t.scheduleType=x.Type;t.coreSubject=x['Core Subject'];t.coreTopic=x['Core Topic'];t.caWindow=x['CA Window'];t.caFocus=x['CA Focus'];t.directQ=Number(x['Direct Q'])||0;t.indirectQ=Number(x['Indirect Q'])||0;});persistEngine();if(!window.__v86InitialScheduleSyncDone){window.__v86InitialScheduleSyncDone=true;toast?.('46 scheduled papers linked to the existing 50-slot engine.','info')}render()}catch(e){console.error(e)}}

  function scheduleEditSave(){const id=document.getElementById('v86ScheduleSelected')?.value;if(!id)return;const ov=scheduleOverrides();const date=document.getElementById('v86EditDate')?.value||'';const meta=date?(()=>{const d=new Date(date+'T00:00:00Z');const days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];return {Day:days[d.getUTCDay()]||'',Month:(months[d.getUTCMonth()]||'')+'-'+d.getUTCFullYear()}})():{Day:'',Month:''};ov[id]={'Core Subject':document.getElementById('v86EditSubject')?.value||'','Core Topic':document.getElementById('v86EditTopic')?.value||'','CA Window':document.getElementById('v86EditCA')?.value||'','CA Focus':document.getElementById('v86EditFocus')?.value||'','Paper Code':document.getElementById('v86EditCode')?.value||'',Date:date,Day:meta.Day,Month:meta.Month,Type:document.getElementById('v86EditType')?.value||'',Level:document.getElementById('v86EditLevel')?.value||'','Test Group':document.getElementById('v86EditGroup')?.value||'','Direct Q':Number(document.getElementById('v86EditDirect')?.value)||0,'Indirect Q':Number(document.getElementById('v86EditIndirect')?.value)||0,'CA-linked Target %':Number(document.getElementById('v86EditCATarget')?.value)||0,Round:document.getElementById('v86EditRound')?.value||'','Stage Focus':document.getElementById('v86EditStage')?.value||'',Timing:document.getElementById('v86EditTiming')?.value||'09:30–11:30 IST','Gap from Previous (days)':Number(document.getElementById('v86EditGap')?.value)||0,'Portal Note':document.getElementById('v86EditNote')?.value||''};saveScheduleOverrides(ov);syncScheduleToEngine();toast?.('Schedule edit saved locally; date/day/month stay synchronized.','info');}
  function csvFromSchedule(){const a=(v86.schedule?.papers||[]).map(x=>({...x,...(scheduleOverrides()[x['Test ID']]||{})}));if(!a.length)return'';const keys=Object.keys(a[0]);return [keys.join(','),...a.map(r=>keys.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(','))].join('\n')}
  function downloadText(name,text,mime){const b=new Blob([text],{type:mime||'text/plain'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}

  function installStartupGate(){
    const root=document.documentElement;
    root.dataset.precisionLock='pending';
    const o=document.getElementById('deviceLockOverlay');
    if(!o)return;
    o.hidden=false;
    const gate=window.precisionSecureGate;
    if(!gate){console.warn('Secure Gate V4 missing; startup remains closed.');return;}
    const card=o.querySelector('.device-lock-card')||o.firstElementChild;
    if(card){card.innerHTML=`
      <div class="lockicon">🔐</div>
      <div class="eyebrow">DEVICE PASSKEY</div>
      <h2 id="secureGateTitle"></h2>
      <p id="secureGateCopy"></p>
      <div id="secureGatePasswordFields" style="display:none">
        <input id="secureGatePassword" type="password" autocomplete="new-password" class="ai-input single" placeholder="Create password (8+ characters)" style="margin:10px 0">
        <input id="secureGateConfirm" type="password" autocomplete="new-password" class="ai-input single" placeholder="Confirm password" style="margin:0 0 10px">
      </div>
      <button class="btn primary" id="secureGatePrimary"></button>
      <button class="btn" id="secureGateFallback" style="margin-top:8px;width:100%"></button>
      <div id="deviceLockError" class="notice error" hidden style="margin-top:10px"></div>
      <div class="notice" style="margin-top:10px">Passkey is local to this browser/device. No credential is sent to Mistral, Vercel or the portal API. If Chrome cannot access the device credential manager, the local password fallback remains available.</div>`;}
    const title=o.querySelector('#secureGateTitle'),copy=o.querySelector('#secureGateCopy'),primary=o.querySelector('#secureGatePrimary'),fallback=o.querySelector('#secureGateFallback'),fields=o.querySelector('#secureGatePasswordFields'),pw=o.querySelector('#secureGatePassword'),cf=o.querySelector('#secureGateConfirm'),err=o.querySelector('#deviceLockError');
    const showErr=m=>{if(err){err.textContent=m||'';err.hidden=!m}};
    const open=async()=>{gate.unlock();o.hidden=true;delete root.dataset.precisionLock;await Promise.resolve(render());};
    const s=gate.state();
    if(s.enabled){
      if(s.mode==='passkey'){
        title.textContent='Unlock PRECISION with your device passkey';copy.textContent='Verify with this device’s screen lock / biometric. The portal remains closed until verification succeeds.';
        primary.textContent='Unlock with device passkey';fallback.textContent='Use local password fallback';
        fallback.onclick=()=>{fields.style.display='block';pw.autocomplete='current-password';cf.style.display='none';pw.placeholder='Portal password';primary.textContent='Unlock with password';primary.onclick=async()=>{const r=await gate.authenticatePassword(pw.value);if(r.ok)open();else showErr(r.msg||'Incorrect password.');};showErr('');pw.focus();};
        primary.onclick=async()=>{showErr('');const r=await gate.authenticate();if(r.ok)open();else showErr(r.msg||'Passkey verification failed. You can use the local password fallback.');};
      }else{
        title.textContent='Enter your local portal password';copy.textContent='This device is protected by the local password fallback. The password never leaves this device.';fields.style.display='block';pw.autocomplete='current-password';cf.style.display='none';pw.placeholder='Portal password';primary.textContent='Unlock PRECISION';fallback.textContent='Reset local security gate';
        primary.onclick=async()=>{showErr('');const r=await gate.authenticatePassword(pw.value);if(r.ok)open();else showErr(r.msg||'Incorrect password.');};
        fallback.onclick=()=>{if(confirm('Reset the local security gate on this browser? You will need to create a new device passkey.')){gate.reset();location.reload();}};
      }
    }else{
      title.textContent='Create a device passkey to open PRECISION';copy.textContent='First-run security gate: create a device passkey. The portal stays closed until passkey verification succeeds.';primary.textContent='Create passkey & open portal';fallback.textContent='Use local password fallback';
      const usePasswordSetup=()=>{showErr('');fields.style.display='block';pw.autocomplete='new-password';cf.style.display='block';pw.placeholder='Create password (8+ characters)';primary.textContent='Create password & open portal';primary.onclick=async()=>{showErr('Creating local password…');const x=await gate.registerPassword(pw.value,cf.value);if(x.ok)await open();else showErr(x.msg);};pw.focus();};
      fallback.onclick=usePasswordSetup;
      primary.onclick=async()=>{showErr('Creating device passkey…');const r=await gate.registerPasskey();if(r.ok){await open();}else{showErr((r.msg||'Passkey creation failed.')+' You can continue with the local password fallback below.');usePasswordSetup();}};
    }
  }

  function bind(){
    if(window.__v86BindInstalled)return;window.__v86BindInstalled=true;
    document.addEventListener('change',ev=>{
      const sel=ev.target.closest?.('#v86ScheduleSelected');
      if(sel){state.__v86ScheduleSelected=sel.value||'';render();return;}
      const web=ev.target.closest?.('#v86AIWeb'),admin=ev.target.closest?.('#v86AIAdmin');
      if(web)setPrefs({web:!!web.checked});
      if(admin)setPrefs({admin:!!admin.checked});
    });
    document.addEventListener('click',async ev=>{
      const f=ev.target.closest?.('[data-v86-followup]');if(f){ev.preventDefault();const p=f.dataset.v86Followup||'';const ta=document.getElementById('v86AIPrompt');if(ta)ta.value=p;return runAI(p);}
      const a=ev.target.closest?.('[data-v86-action]')?.dataset.v86Action;if(!a)return;
      try{
        if(a==='ai-run')return runAI();
        if(a==='ai-new')return newConversation();
        if(a==='ai-clear'){const x=document.getElementById('v86AIPrompt');if(x)x.value='';return}
        if(a==='ai-page'){const p=ev.target.closest('[data-v86-action]')?.dataset.aiPrompt||`Analyse the current ${state.view} page.`;setView('ai');setTimeout(()=>{const x=document.getElementById('v86AIPrompt');if(x){x.value=p;x.focus()}},40);return}
        if(a==='ai-weekly'){setView('ai');setTimeout(()=>runAI(reportPrompt(),{web:false}).catch(()=>{}),60);return}
        if(a==='ai-save-weekly'){const last=read(KEY.last,{reply:''});if(last.reply)write(KEY.weekly,{at:isoNow(),reply:last.reply,prompt:last.prompt});toast?.('Last AI response saved as weekly report.','info');render();return}
        if(a==='ai-export-weekly'){const r=read(KEY.weekly,{reply:'',prompt:'',at:null});if(!r.reply){toast?.('No saved weekly report to export.','error');return}downloadText('precision-ai-weekly-report-v861.txt',`PRECISION AI WEEKLY REPORT\nGenerated: ${r.at||''}\n\n${r.reply}`,'text/plain');return}
        if(a==='ai-export-memory'){downloadText('precision-ai-memory-v861.json',JSON.stringify({version:V,memory:memory(),training:training()},null,2),'application/json');return}
        if(a==='ai-import-memory'){const f=document.getElementById('v86MemoryFile');if(f){f.onchange=async()=>{const file=f.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.memory)||!Array.isArray(data.training))throw new Error('Invalid Precision AI backup format');write(KEY.mem,data.memory.slice(0,300));write(KEY.train,data.training.slice(0,120));state.aiHistory=data.memory.slice(0,50);render();toast?.('AI memory/training restored from backup.','info')}catch(e){toast?.(e.message||'AI backup restore failed','error')}};f.click()}return}
        if(a==='ai-export'){downloadText('precision-ai-response-v861.txt',v86.lastReply||read(KEY.last,{reply:''}).reply||'','text/plain');return}
        if(a==='ai-save-training'){const last=read(KEY.last,{reply:'',prompt:''});const t=window.prompt('Training title','AI answer rule / source note');if(t&&last.reply){saveTraining(t,last.reply);render();toast?.('Saved to AI training memory.','info')}return}
        if(a==='ai-train-open'){showTrainingModal();return}
        if(a==='ai-train-save'){const t=document.getElementById('v86TrainTitle')?.value.trim(),c=document.getElementById('v86TrainText')?.value.trim();if(!c)return;if(t)saveTraining(t,c);document.querySelector('.v86-modal')?.remove();toast?.('Trusted training note saved locally.','info');render();return}
        if(a==='ai-code-audit'){const manifest=state.manifest||{};setView('ai');setTimeout(()=>runAI('Audit the supplied Precision system manifest. Explain architecture risks, missing linkages, performance bottlenecks and precise recommended changes. Do not fabricate file contents. Manifest: '+JSON.stringify(manifest),{web:false,admin:true}),60);return}
        if(a==='ai-omr'){setView('attempt');setTimeout(()=>runAI('Audit the current OMR/evaluation state. Check extraction quality, ambiguity, answer-key readiness and exact next step using my portal data.',{web:false}),60);return}
        if(a==='focus-toggle'){const next=!document.body.classList.contains('v86-focus-view');setPrefs({focusMode:next});document.body.classList.toggle('v86-focus-view',next);render();return}
        if(a==='nav-back'){const st=navStack();const v=st.pop()||'overview';saveNav(st);setView(v,{noStack:true});return}
        if(a==='close-modal'){document.querySelector('.v86-modal')?.remove();return}
        if(a==='admin-open'){showAdminModal();return}
        if(a==='admin-run'){const p=document.getElementById('v86AdminPrompt')?.value.trim();if(!p)return;const box=document.getElementById('v86AdminResult');if(box)box.textContent='Running safe admin command…';const old=document.getElementById('v86AIAdmin');if(old)old.checked=true;try{const resp=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:p+'\nADMIN MODE: Return safe actions using <PORTAL_ACTIONS> JSON when needed. Allowed only: navigate, open_omr, select_mock, set_study_target, save_note, set_schedule_date, show_report, focus, lock_portal. No destructive changes.',web:false,conversationId:null,context:buildContext(p,false,true)})});if(!resp.ok)throw new Error('AI admin '+resp.status);let text='';await readStream(resp,x=>text+=x,()=>{});const parsed=parseActions(text);const notes=applyActions(parsed.actions);if(box)box.textContent=(parsed.text||'Admin command completed.')+' '+notes.join(' • ');}catch(e){if(box)box.textContent='Admin error: '+e.message}return}
        if(a==='official-key-test'){state.__v86KeyTest=Number(ev.target.closest('[data-v86-action]')?.dataset.testNo||1);render();return}
        if(a==='official-key-save'){const file=document.getElementById('v86OfficialFile')?.files?.[0];if(!file){toast?.('Choose the official answer-key file.','error');return}const no=Number(document.getElementById('v86OfficialTest')?.value||1),code=document.getElementById('v86OfficialCode')?.value.trim()||'';const txt=await file.text();const key=parseOfficialKeyFile(txt);if(Object.keys(key).length!==100){toast?.(`Official key parsed ${Object.keys(key).length}/100. Check the file format.`,'error');return}const t=engineState().tests.find(x=>x.testNo===no);if(!t||t.paperCode!==code){toast?.('Paper code mismatch. Select the exact scheduled paper code.','error');return}const evs=evalState();evs.officialKeys ||= {};evs.officialKeyMeta ||= {};evs.officialKeys[no]=key;evs.officialKeyMeta[no]={file:file.name,paperCode:code,updatedAt:Date.now(),source:'OFFICIAL_TAB_V86'};persistEval();state.__v86KeyTest=no;render();cloudSyncSoon();toast?.('Official answer key saved separately and bound to the paper code.','info');return}
        if(a==='official-key-export'){const no=Number(document.getElementById('v86OfficialTest')?.value||state.__v86KeyTest||1),key=evalState().officialKeys?.[no]||{};if(Object.keys(key).length!==100){toast?.('No complete official key is saved for this test.','error');return}downloadText(`mock-${String(no).padStart(2,'0')}-official-answer-key-v861.txt`,buildAnswerKeyText(key),'text/plain');return}
        if(a==='schedule-workbook'){showScheduleWorkbookModal();return}
        if(a==='schedule-export-json'){downloadText('precision-upsc-2027-schedule-source-v861.json',JSON.stringify(v86.schedule,null,2),'application/json');return}
        if(a==='schedule-search'){state.__v86ScheduleQ=document.getElementById('v86ScheduleSearch')?.value||'';state.__v86ScheduleType=document.getElementById('v86ScheduleType')?.value||'ALL';state.__v86ScheduleMonth=document.getElementById('v86ScheduleMonth')?.value||'ALL';render();return}
        if(a==='schedule-reset'){state.__v86ScheduleQ='';state.__v86ScheduleType='ALL';state.__v86ScheduleMonth='ALL';render();return}
        if(a==='schedule-select'){state.__v86ScheduleSelected=ev.target.closest('[data-schedule-id]')?.dataset.scheduleId||'';render();return}
        if(a==='schedule-save-edit'){scheduleEditSave();return}
        if(a==='schedule-export'){downloadText('precision-upsc-2027-schedule-edited-v861.csv',csvFromSchedule(),'text/csv');return}
        if(a==='schedule-reset-source'){saveScheduleOverrides({});render();toast?.('Schedule edits reset to source workbook.','info');return}
        if(a==='schedule-sync-engine'){syncScheduleToEngine();return}
        if(a==='schedule-ai-brief'||a==='schedule-ai-conflict'||a==='schedule-ai-plan'||a==='schedule-ai-ca'||a==='schedule-ai-load'||a==='schedule-ai-selected'){const sel=state.__v86ScheduleSelected||'';const prompts={
          'schedule-ai-brief':`Give an AI pre-test brief for the next scheduled paper: syllabus focus, CA window, likely skill modes, revision checklist. Use schedule data only; do not predict exact questions.`,
          'schedule-ai-conflict':`Audit the full 46-paper schedule for date spacing, blackout conflicts, repeated subject load, CA-window fit and engine mapping. Identify exact conflicts found in supplied data.`,
          'schedule-ai-plan':`Create my next 7-day test + study plan linked to the actual schedule and my current study ledger.`,
          'schedule-ai-ca':`Audit CA windows across all 46 scheduled tests and show where the cutoff/source hierarchy should drive my current-affairs work.`,
          'schedule-ai-load':`Analyse subject/test load across the 46-paper schedule and compare it with supplied Prelims and Mains trend weightage.`,
          'schedule-ai-selected':`Analyse selected scheduled paper ${sel}: topic scope, CA window, direct/indirect mix, related Mains domains and preparation checklist.`};setView('ai');setTimeout(()=>runAI(prompts[a],{web:false}),70);return}
        if(a==='schedule-next'){state.__v86ScheduleSelected=((v86.schedule?.papers||[]).find(x=>new Date(`${x.Date}T09:30:00+05:30`).getTime()>Date.now())||v86.schedule?.papers?.[0])?.['Test ID']||'';render();return}
        if(a==='close-modal')document.querySelector('.v86-modal')?.remove();
      }catch(e){console.error(e);toast?.(e.message||'V8.6 action failed','error')}
    });
  }

